_g": "1.2", "processing_level": "Whole/Unprocessed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
