rotein": "6g", "carbs": "6g", "sugar": "1g", "fat": "14g", "fiber": "4g", "cholesterol": "0mg", "quick_reference_servings": [{"Nutrient": "Calcium", "Amount": "80mg"}, {"Nutrient": "Iron", "Amount": "1mg"}, {"Nutrient": "Potassium", "Amount": "220mg"}, {"Nutrient": "Sodium", "Amount": "0mg"}], "tags": "", "food_category": "fat", "source": "notion", "notion_category": "Fat", "serving_unit": "1/4 cup (30g)", "serving_unit_g": "30", "calories_per_unit": "160", "protein_per_unit_g": "6", "carbs_per_unit_g": "6", "fat_per_unit_g": "14", "fiber_per_unit_g": "4", "sugar_per_unit_g": "1", "cholesterol_per_unit_mg": "0", "processing_level": "Whole/Unprocessed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Avocado Oil', 'fat', 120, 0, 0, 12, 0, 0, false, '{"content_hash": "7a937887253491d0496292dcdebe214a", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/fat\nfood_category: fat\nsource: notion\nnotion_category: Fat\nserving_unit: \"1 tbsp\"\ncalories_per_unit: 120\nprotein_per_unit_g: 0\ncarbs_per_unit_g: 0\nfat_per_unit_g: 12\nprocessing_level: \"Minimally Processed\"\nfermented: false\n---\n# Avocado Oil\n\nMigrated from Notion''s Foods database. Data is per serving **unit**, not per 100g \u2014 a sparser reference than the vault''s primary food-library entries. See also [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] for the whole-fruit entry.\n\n## Macros (per unit)\n\n| Unit | Calories | Protein | Carbs | Fat |\n|---|---|---|---|---|\n| 1 tbsp | 120 | 0g | 0g | 12g |\n\n## Classification\n\n- **Category:** Fat\n- **Processing Level:** Minimally Processed\n- **Fermented:** No\n", "portion_state": "unspecified", "tables": [{"headers": ["Unit", "Calories", "Protein", "Carbs", "Fat"], "rows": [{"Unit": "1 tbsp", "Calories": "120", "Protein": "0g", "Carbs": "0g", "Fat": "12g"}]}], "unit": "1 tbsp", "calories": "120", "protein": "0g", "carbs": "0g", "fat": "12g", "tags": "", "food_category": "fat", "source": "notion", "notion_category": "Fat", "serving_unit": "1 tbsp", "calories_per_unit": "120", "protein_per_unit_g": "0", "carbs_per_unit_g": "0", "fat_per_unit_g": "12", "processing_level": "Minimally Processed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Avocado', 'fat', 160, 2.0, 8.5, 14.7, 6.7, 110, false, '{"content_hash": "1ed5a9a980749701890f2900e4d2765f", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/fat\nfood_category: fat\n# Macros per 100g\ncalories_per_100g: 160\nprotein_per_100g: 2.0\ncarbs_per_100g: 8.5\nsugar_per_100g: 0.7\nadded_sugar: false\nfat_per_100g: 14.7\nsaturated_fat_per_100g: 2.1\nfibre_per_100g: 6.7\ncholesterol_per_100g: 0\n# Omega-3\nomega3_per_100g_mg: 110\n# Key minerals per 100g (mg unless noted)\niron_per_100g: 0.6\nzinc_per_100g: 0.6\nmagnesium_per_100g: 29\npotassium_per_100g: 485\nsodium_per_100g: 7\nselenium_per_100g_\u00b5g: 0.4\ncholine_per_100g_mg: 14\n# Key vitamins per 100g\nvitamin_c_per_100g_mg: 10\nvitamin_d_per_100g_iu: 0\nvitamin_b12_per_100g_\u00b5g: 0\n# Protein quality\ncomplete_protein: false\nleucine_per_100g: 0.18\n# Good Energy attributes\nantioxidant_level: moderate\nprobiotic: false\nrefined: false\nseed_oil: false\n# Body systems\nbody_systems:\n  - heart\n  - brain\n  - gut\n  - mitochondria\n  - eyes\n  - skin\n  - hormones\n# Serving\nserving_unit: g\nserving_unit_g: 1\ntypical_serving: \u00bd avocado (100g)\ntypical_serving_g: 100\n# Classification\nglycaemic_index: 15\nmitochondrial_benefit: high\n---\n# Avocado\n\n> [!success] Sports Nutrition Snapshot\n> **14.7g fat / 100g (monounsaturated)** \u00b7 **6.7g fibre / 100g** \u00b7 **GI: 15** \u00b7 **Mitochondrial benefit: High**\n> The rare food that simultaneously delivers fat, fibre, and anti-inflammatory compounds \u2014 doing three jobs at once.\n\n> [!quote]\n> \"Avocado is the rare food that is simultaneously a fat source, a fibre source, and an anti-inflammatory \u2014 it does three jobs at once.\" \u2014 Casey Means\n\nAvocado is the most nutrient-dense everyday fat source available. Its fat profile is predominantly oleic acid \u2014 the same monounsaturated fat found in olive oil \u2014 which is anti-inflammatory, does not oxidise easily, and integrates cleanly into mitochondrial membranes. It is also one of the highest-fibre foods available, making it uniquely filling relative to its calorie content.\n\n---\n\n## Macros\n\n### Per 100g\n\n| Calories | Protein | Carbs | Sugar | Net Carbs | Fat | Sat. Fat | Fibre | Cholesterol |\n|---|---|---|---|---|---|---|---|---|\n| 160 | 2.0g | 8.5g | 0.7g | 1.8g | 14.7g | 2.1g | 6.7g | 0mg |\n\n> [!info] Net Carbs = Total Carbs \u2212 Fibre\n> The fibre in avocado is almost entirely insoluble and does not raise blood glucose. Net carbs \u2014 the glucose-active portion \u2014 are very low at 1.8g per 100g.\n\n### Quick Reference\n\n| Amount | Cal | Fat | Net Carbs | Fibre | Potassium |\n|---|---|---|---|---|---|\n| \u00bd small (75g) | 120 | 11.0g | 1.4g | 5.0g | 364mg |\n| \u00bd medium (100g) | 160 | 14.7g | 1.8g | 6.7g | 485mg |\n| \u00be medium (150g) | 240 | 22.1g | 2.7g | 10.1g | 728mg |\n| 1 whole (200g) | 320 | 29.4g | 3.6g | 13.4g | 970mg |\n\n---\n\n## Minerals\n\n| Mineral | Per 100g | % RDA | Role |\n|---|---|---|---|\n| Potassium | 485mg | 10% | Blood pressure regulation; muscle contraction and recovery; more per gram than banana |\n| Copper | 0.19mg | 21% | SOD1 antioxidant enzyme cofactor; iron metabolism and absorption |\n| Magnesium | 29mg | 7% | ATP synthesis; muscle relaxation; 50%+ of population deficient |\n| Phosphorus | 52mg | 4% | ATP production; bone mineralisation |\n| Iron | 0.6mg | 3\u20138% | Oxygen transport; mitochondrial electron chain |\n| Zinc | 0.6mg | 5\u20138% | Protein synthesis; immune function |\n| Sodium | 7mg | \u2014 | Naturally very low \u2014 suitable for sodium-restricted diets |\n\n---\n\n## Vitamins\n\n| Vitamin | Per 100g | % RDA | Role |\n|---|---|---|---|\n| Folate | 81\u00b5g | 20% | DNA synthesis; methylation reactions; neurological development |\n| Vitamin K | 21\u00b5g | 18\u201326% | Bone mineralisation; coagulation; arterial calcification protection |\n| Vitamin E | 2.1mg | 14% | Fat-soluble antioxidant; protects avocado''s own monounsaturated fat from oxidation in the body |\n| Vitamin C | 10mg | 11% | Antioxidant; collagen synthesis; iron absorption enhancement |\n| Vitamin B6 | 0.26mg | 20% | Protein metabolism; neurotransmitter synthesis |\n\n---\n\n## Fat Profile\n\n> [!tip] Oleic acid \u2014 the same fat as olive oil\n> ~10g of avocado''s 14.7g fat per 100g is oleic acid (monounsaturated omega-9). This is the fat most associated with anti-inflammatory effects, cardiovascular protection, and mitochondrial membrane stability. Unlike polyunsaturated fats (especially omega-6), oleic acid does not oxidise readily at body temperature and does not generate the oxidative stress that seed oils produce.\n\n| Fat Type | Per 100g | Properties |\n|---|---|---|\n| Oleic acid (monounsaturated) | ~10g | Anti-inflammatory; stable; integrates into cell membranes without oxidative stress |\n| Palmitic acid (saturated) | ~2.1g | Neutral to slightly pro-inflammatory at high intake; well within safe range here |\n| Linoleic acid (omega-6) | ~1.7g | Low relative to total fat \u2014 not a seed-oil omega-6 concern |\n| Alpha-linolenic acid (omega-3) | ~0.11g | ALA; minimal EPA/DHA conversion |\n\n---\n\n## Food Synergies\n\n| Paired With | Synergy | Mechanism |\n|---|---|---|\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] | Fat-soluble vitamin absorption | Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 fat must be present for these vitamins to absorb; co-ingestion substantially increases their bioavailability |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] | Polyphenol bioavailability | Avocado fat dramatically increases the absorption of blueberries'' fat-soluble phytonutrients (beta-carotene, lutein, zeaxanthin); one of the best-evidenced food pairings for nutrient bioavailability |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] | Anti-inflammatory fat synergy | Monounsaturated fat (avocado) + EPA/DHA (salmon) together cover the full anti-inflammatory lipid spectrum; zero glucose impact; complementary fat profiles with no overlapping risks |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]] | Satiety extension | Fat slows gastric emptying and prolongs satiety from lean protein; potassium from avocado supports muscle recovery and electrolyte balance after training |\n\n---\n\n## Dosage Guidance\n\n> [!info] Calorie density is the main consideration\n> **Optimal per meal: \u00bd avocado (75\u2013100g)**\n> - Provides 120\u2013160 calories, 5\u20136.7g fibre, and the full micronutrient benefit\n> - A whole avocado (200g) = ~320 calories, predominantly fat \u2014 appropriate on higher-calorie days or as the primary fat source for a meal\n>\n> **No cholesterol** \u2014 avocado contains no dietary cholesterol whatsoever. Saturated fat is low (2.1g/100g) \u2014 the primary fat is oleic acid, which does not raise LDL meaningfully and may improve the LDL-to-HDL ratio.\n>\n> **No upper limit concern** beyond total calorie budget. Unlike seed oils, avocado fat does not carry oxidative stress, pro-inflammatory omega-6 load, or processing-related compounds.\n>\n> **Ripening:** avocados ripen at room temperature (2\u20135 days from firm). Refrigerate once ripe to extend by 2\u20133 days. The fat profile shifts slightly toward more monounsaturated fat as the fruit ripens \u2014 eat at peak ripeness.\n\n---\n\n## Good Energy Relevance\n\nAvocado is one of three foods in the vault (alongside oats and blueberries) that contributes meaningfully to the 50g/day fibre target \u2014 100g provides 6.7g fibre, the highest of any commonly eaten fatty food. The oleic acid integrates into mitochondrial membranes without the oxidative stress that polyunsaturated seed oils generate. The fat content makes avocado one of the most effective glucose-blunting additions to any meal.\n\n**Good Energy daily targets contribution (per 100g):**\n- Fibre: 6.7g of 50g target (13%)\n- Omega-3: 110mg of 2,000mg target (ALA, minimal)\n- Antioxidants: moderate (vitamin E, lutein, zeaxanthin, glutathione \u2014 richest fruit source of glutathione)\n- Probiotics: none\n\n---\n\n## Meal Ideas\n\nSliced over chicken or salmon \u00b7 Mashed alongside eggs \u00b7 As the fat source in a salad in place of dressing \u00b7 With blueberries as a snack (fat enhances polyphenol absorption)\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]]\n\n---\n\n## From Notion (unit-based reference)\n\nNotion''s Foods database classified Avocado as **Processing Level: Whole/Unprocessed**, **Fermented: No** \u2014 consistent with this file, no changes needed. Its serving reference was 1 whole avocado (200g) = 322 cal / 4g protein / 17g carbs / 29g fat / 13g fibre / 0mg cholesterol / 975mg potassium \u2014 in line with the Quick Reference table above.\n", "portion_state": "unspecified", "tables": [{"headers": ["Calories", "Protein", "Carbs", "Sugar", "Net Carbs", "Fat", "Sat. Fat", "Fibre", "Cholesterol"], "rows": [{"Calories": "160", "Protein": "2.0g", "Carbs": "8.5g", "Sugar": "0.7g", "Net Carbs": "1.8g", "Fat": "14.7g", "Sat. Fat": "2.1g", "Fibre": "6.7g", "Cholesterol": "0mg"}]}, {"headers": ["Amount", "Cal", "Fat", "Net Carbs", "Fibre", "Potassium"], "rows": [{"Amount": "\u00bd small (75g)", "Cal": "120", "Fat": "11.0g", "Net Carbs": "1.4g", "Fibre": "5.0g", "Potassium": "364mg"}, {"Amount": "\u00bd medium (100g)", "Cal": "160", "Fat": "14.7g", "Net Carbs": "1.8g", "Fibre": "6.7g", "Potassium": "485mg"}, {"Amount": "\u00be medium (150g)", "Cal": "240", "Fat": "22.1g", "Net Carbs": "2.7g", "Fibre": "10.1g", "Potassium": "728mg"}, {"Amount": "1 whole (200g)", "Cal": "320", "Fat": "29.4g", "Net Carbs": "3.6g", "Fibre": "13.4g", "Potassium": "970mg"}]}, {"headers": ["Mineral", "Per 100g", "% RDA", "Role"], "rows": [{"Mineral": "Potassium", "Per 100g": "485mg", "% RDA": "10%", "Role": "Blood pressure regulation; muscle contraction and recovery; more per gram than banana"}, {"Mineral": "Copper", "Per 100g": "0.19mg", "% RDA": "21%", "Role": "SOD1 antioxidant enzyme cofactor; iron metabolism and absorption"}, {"Mineral": "Magnesium", "Per 100g": "29mg", "% RDA": "7%", "Role": "ATP synthesis; muscle relaxation; 50%+ of population deficient"}, {"Mineral": "Phosphorus", "Per 100g": "52mg", "% RDA": "4%", "Role": "ATP production; bone mineralisation"}, {"Mineral": "Iron", "Per 100g": "0.6mg", "% RDA": "3\u20138%", "Role": "Oxygen transport; mitochondrial electron chain"}, {"Mineral": "Zinc", "Per 100g": "0.6mg", "% RDA": "5\u20138%", "Role": "Protein synthesis; immune function"}, {"Mineral": "Sodium", "Per 100g": "7mg", "% RDA": "\u2014", "Role": "Naturally very low \u2014 suitable for sodium-restricted diets"}]}, {"headers": ["Vitamin", "Per 100g", "% RDA", "Role"], "rows": [{"Vitamin": "Folate", "Per 100g": "81\u00b5g", "% RDA": "20%", "Role": "DNA synthesis; methylation reactions; neurological development"}, {"Vitamin": "Vitamin K", "Per 100g": "21\u00b5g", "% RDA": "18\u201326%", "Role": "Bone mineralisation; coagulation; arterial calcification protection"}, {"Vitamin": "Vitamin E", "Per 100g": "2.1mg", "% RDA": "14%", "Role": "Fat-soluble antioxidant; protects avocado''s own monounsaturated fat from oxidation in the body"}, {"Vitamin": "Vitamin C", "Per 100g": "10mg", "% RDA": "11%", "Role": "Antioxidant; collagen synthesis; iron absorption enhancement"}, {"Vitamin": "Vitamin B6", "Per 100g": "0.26mg", "% RDA": "20%", "Role": "Protein metabolism; neurotransmitter synthesis"}]}, {"headers": ["Fat Type", "Per 100g", "Properties"], "rows": [{"Fat Type": "Oleic acid (monounsaturated)", "Per 100g": "~10g", "Properties": "Anti-inflammatory; stable; integrates into cell membranes without oxidative stress"}, {"Fat Type": "Palmitic acid (saturated)", "Per 100g": "~2.1g", "Properties": "Neutral to slightly pro-inflammatory at high intake; well within safe range here"}, {"Fat Type": "Linoleic acid (omega-6)", "Per 100g": "~1.7g", "Properties": "Low relative to total fat \u2014 not a seed-oil omega-6 concern"}, {"Fat Type": "Alpha-linolenic acid (omega-3)", "Per 100g": "~0.11g", "Properties": "ALA; minimal EPA/DHA conversion"}]}, {"headers": ["Paired With", "Synergy", "Mechanism"], "rows": [{"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]]", "Synergy": "Fat-soluble vitamin absorption", "Mechanism": "Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 fat must be present for these vitamins to absorb; co-ingestion substantially increases their bioavailability"}, {"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]]", "Synergy": "Polyphenol bioavailability", "Mechanism": "Avocado fat dramatically increases the absorption of blueberries'' fat-soluble phytonutrients (beta-carotene, lutein, zeaxanthin); one of the best-evidenced food pairings for nutrient bioavailability"}, {"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]]", "Synergy": "Anti-inflammatory fat synergy", "Mechanism": "Monounsaturated fat (avocado) + EPA/DHA (salmon) together cover the full anti-inflammatory lipid spectrum; zero glucose impact; complementary fat profiles with no overlapping risks"}, {"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]]", "Synergy": "Satiety extension", "Mechanism": "Fat slows gastric emptying and prolongs satiety from lean protein; potassium from avocado supports muscle recovery and electrolyte balance after training"}]}], "calories": "160", "protein": "2.0g", "carbs": "8.5g", "sugar": "0.7g", "net_carbs": "1.8g", "fat": "14.7g", "sat._fat": "2.1g", "fibre": "6.7g", "cholesterol": "0mg", "quick_reference_servings": [{"Amount": "\u00bd small (75g)", "Cal": "120", "Fat": "11.0g", "Net Carbs": "1.4g", "Fibre": "5.0g", "Potassium": "364mg"}, {"Amount": "\u00bd medium (100g)", "Cal": "160", "Fat": "14.7g", "Net Carbs": "1.8g", "Fibre": "6.7g", "Potassium": "485mg"}, {"Amount": "\u00be medium (150g)", "Cal": "240", "Fat": "22.1g", "Net Carbs": "2.7g", "Fibre": "10.1g", "Potassium": "728mg"}, {"Amount": "1 whole (200g)", "Cal": "320", "Fat": "29.4g", "Net Carbs": "3.6g", "Fibre": "13.4g", "Potassium": "970mg"}], "minerals_breakdown": [{"Mineral": "Potassium", "Per 100g": "485mg", "% RDA": "10%", "Role": "Blood pressure regulation; muscle contraction and recovery; more per gram than banana"}, {"Mineral": "Copper", "Per 100g": "0.19mg", "% RDA": "21%", "Role": "SOD1 antioxidant enzyme cofactor; iron metabolism and absorption"}, {"Mineral": "Magnesium", "Per 100g": "29mg", "% RDA": "7%", "Role": "ATP synthesis; muscle relaxation; 50%+ of population deficient"}, {"Mineral": "Phosphorus", "Per 100g": "52mg", "% RDA": "4%", "Role": "ATP production; bone mineralisation"}, {"Mineral": "Iron", "Per 100g": "0.6mg", "% RDA": "3\u20138%", "Role": "Oxygen transport; mitochondrial electron chain"}, {"Mineral": "Zinc", "Per 100g": "0.6mg", "% RDA": "5\u20138%", "Role": "Protein synthesis; immune function"}, {"Mineral": "Sodium", "Per 100g": "7mg", "% RDA": "\u2014", "Role": "Naturally very low \u2014 suitable for sodium-restricted diets"}], "vitamins_breakdown": [{"Vitamin": "Folate", "Per 100g": "81\u00b5g", "% RDA": "20%", "Role": "DNA synthesis; methylation reactions; neurological development"}, {"Vitamin": "Vitamin K", "Per 100g": "21\u00b5g", "% RDA": "18\u201326%", "Role": "Bone mineralisation; coagulation; arterial calcification protection"}, {"Vitamin": "Vitamin E", "Per 100g": "2.1mg", "% RDA": "14%", "Role": "Fat-soluble antioxidant; protects avocado''s own monounsaturated fat from oxidation in the body"}, {"Vitamin": "Vitamin C", "Per 100g": "10mg", "% RDA": "11%", "Role": "Antioxidant; collagen synthesis; iron absorption enhancement"}, {"Vitamin": "Vitamin B6", "Per 100g": "0.26mg", "% RDA": "20%", "Role": "Protein metabolism; neurotransmitter synthesis"}], "food_synergies": [{"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]]", "Synergy": "Fat-soluble vitamin absorption", "Mechanism": "Avocado''s monounsaturated fat acts as a carrier for eggs'' fat-soluble vitamins (A, D, E, K) \u2014 fat must be present for these vitamins to absorb; co-ingestion substantially increases their bioavailability"}, {"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]]", "Synergy": "Polyphenol bioavailability", "Mechanism": "Avocado fat dramatically increases the absorption of blueberries'' fat-soluble phytonutrients (beta-carotene, lutein, zeaxanthin); one of the best-evidenced food pairings for nutrient bioavailability"}, {"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]]", "Synergy": "Anti-inflammatory fat synergy", "Mechanism": "Monounsaturated fat (avocado) + EPA/DHA (salmon) together cover the full anti-inflammatory lipid spectrum; zero glucose impact; complementary fat profiles with no overlapping risks"}, {"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]]", "Synergy": "Satiety extension", "Mechanism": "Fat slows gastric emptying and prolongs satiety from lean protein; potassium from avocado supports muscle recovery and electrolyte balance after training"}], "tags": "", "food_category": "fat", "calories_per_100g": "160", "protein_per_100g": "2.0", "carbs_per_100g": "8.5", "sugar_per_100g": "0.7", "added_sugar": "false", "fat_per_100g": "14.7", "saturated_fat_per_100g": "2.1", "fibre_per_100g": "6.7", "cholesterol_per_100g": "0", "omega3_per_100g_mg": "110", "iron_per_100g": "0.6", "zinc_per_100g": "0.6", "magnesium_per_100g": "29", "potassium_per_100g": "485", "sodium_per_100g": "7", "selenium_per_100g_\u00b5g": "0.4", "choline_per_100g_mg": "14", "vitamin_c_per_100g_mg": "10", "vitamin_d_per_100g_iu": "0", "vitamin_b12_per_100g_\u00b5g": "0", "complete_protein": "false", "leucine_per_100g": "0.18", "antioxidant_level": "moderate", "probiotic": "false", "refined": "false", "seed_oil": "false", "body_systems": "", "serving_unit": "g", "serving_unit_g": "1", "typical_serving": "\u00bd avocado (100g)", "typical_serving_g": "100", "glycaemic_index": "15", "mitochondrial_benefit": "high", "callouts": [{"type": "success", "title": "Sports Nutrition Snapshot", "content": "**14.7g fat / 100g (monounsaturated)** \u00b7 **6.7g fibre / 100g** \u00b7 **GI: 15** \u00b7 **Mitochondrial benefit: High**\nThe rare food that simultaneously delivers fat, fibre, and anti-inflammatory compounds \u2014 doing three jobs at once."}, {"type": "quote", "title": "\"Avocado is the rare food that is simultaneously a fat source, a fibre source, and an anti-inflammatory \u2014 it does three jobs at once.\" \u2014 Casey Means", "content": ""}, {"type": "info", "title": "Net Carbs = Total Carbs \u2212 Fibre", "content": "The fibre in avocado is almost entirely insoluble and does not raise blood glucose. Net carbs \u2014 the glucose-active portion \u2014 are very low at 1.8g per 100g."}, {"type": "tip", "title": "Oleic acid \u2014 the same fat as olive oil", "content": "~10g of avocado''s 14.7g fat per 100g is oleic acid (monounsaturated omega-9). This is the fat most associated with anti-inflammatory effects, cardiovascular protection, and mitochondrial membrane stability. Unlike polyunsaturated fats (especially omega-6), oleic acid does not oxidise readily at body temperature and does not generate the oxidative stress that seed oils produce."}, {"type": "info", "title": "Calorie density is the main consideration", "content": "**Optimal per meal: \u00bd avocado (75\u2013100g)**\n- Provides 120\u2013160 calories, 5\u20136.7g fibre, and the full micronutrient benefit\n- A whole avocado (200g) = ~320 calories, predominantly fat \u2014 appropriate on higher-calorie days or as the primary fat source for a meal\n\n**No cholesterol** \u2014 avocado contains no dietary cholesterol whatsoever. Saturated fat is low (2.1g/100g) \u2014 the primary fat is oleic acid, which does not raise LDL meaningfully and may improve the LDL-to-HDL ratio.\n\n**No upper limit concern** beyond total calorie budget. Unlike seed oils, avocado fat does not carry oxidative stress, pro-inflammatory omega-6 load, or processing-related compounds.\n\n**Ripening:** avocados ripen at room temperature (2\u20135 days from firm). Refrigerate once ripe to extend by 2\u20133 days. The fat profile shifts slightly toward more monounsaturated fat as the fruit ripens \u2014 eat at peak ripeness."}], "quotes": ["\"Avocado is the rare food that is simultaneously a fat source, a fibre source, and an anti-inflammatory \u2014 it does three jobs at once.\" \u2014 Casey Means"], "dosage_and_timing_guidance": "> [!info] Calorie density is the main consideration\n> **Optimal per meal: \u00bd avocado (75\u2013100g)**\n> - Provides 120\u2013160 calories, 5\u20136.7g fibre, and the full micronutrient benefit\n> - A whole avocado (200g) = ~320 calories, predominantly fat \u2014 appropriate on higher-calorie days or as the primary fat source for a meal\n>\n> **No cholesterol** \u2014 avocado contains no dietary cholesterol whatsoever. Saturated fat is low (2.1g/100g) \u2014 the primary fat is oleic acid, which does not raise LDL meaningfully and may improve the LDL-to-HDL ratio.\n>\n> **No upper limit concern** beyond total calorie budget. Unlike seed oils, avocado fat does not carry oxidative stress, pro-inflammatory omega-6 load, or processing-related compounds.\n>\n> **Ripening:** avocados ripen at room temperature (2\u20135 days from firm). Refrigerate once ripe to extend by 2\u20133 days. The fat profile shifts slightly toward more monounsaturated fat as the fruit ripens \u2014 eat at peak ripeness.\n\n---", "meal_ideas": "Sliced over chicken or salmon \u00b7 Mashed alongside eggs \u00b7 As the fat source in a salad in place of dressing \u00b7 With blueberries as a snack (fat enhances polyphenol absorption)\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Chicken Breast]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]]\n\n---", "good_energy_relevance": "Avocado is one of three foods in the vault (alongside oats and blueberries) that contributes meaningfully to the 50g/day fibre target \u2014 100g provides 6.7g fibre, the highest of any commonly eaten fatty food. The oleic acid integrates into mitochondrial membranes without the oxidative stress that polyunsaturated seed oils generate. The fat content makes avocado one of the most effective glucose-blunting additions to any meal.\n\n**Good Energy daily targets contribution (per 100g):**\n- Fibre: 6.7g of 50g target (13%)\n- Omega-3: 110mg of 2,000mg target (ALA, minimal)\n- Antioxidants: moderate (vitamin E, lutein, zeaxanthin, glutathione \u2014 richest fruit source of glutathione)\n- Probiotics: none\n\n---"}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Banana', 'carb', 105, 1.3, 27, 0.4, 0, 0, false, '{"content_hash": "012b1fd3699dc97df71171e8bb9f35ef", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/carb\nfood_category: carb\nsource: notion\nnotion_category: Carb\nserving_unit: \"1 medium banana\"\ncalories_per_unit: 105\nprotein_per_unit_g: 1.3\ncarbs_per_unit_g: 27\nfat_per_unit_g: 0.4\nfiber_per_unit_g: 3.1\nsugar_per_unit_g: 14\nprocessing_level: \"Whole/Unprocessed\"\nfermented: false\n---\n# Banana\n\nMigrated from Notion''s Foods database. Data is per serving **unit**, not per 100g \u2014 a sparser reference than the vault''s primary food-library entries.\n\n## Macros (per unit)\n\n| Unit | Calories | Protein | Carbs | Sugar | Fat | Fiber |\n|---|---|---|---|---|---|---|\n| 1 medium banana | 105 | 1.3g | 27g | 14g | 0.4g | 3.1g |\n\n## Micronutrients (per unit)\n\n| Nutrient | Amount |\n|---|---|\n| Calcium | 5.9mg |\n| Iron | 0.3mg |\n| Potassium | 422mg |\n| Sodium | 1.2mg |\n\n## Classification\n\n- **Category:** Carb\n- **Processing Level:** Whole/Unprocessed\n- **Fermented:** No\n\n## Health Benefits\n\nGood source of potassium for heart health, provides quick energy.\n\n## Notes\n\nEasy grab-and-go snack.\n", "portion_state": "unspecified", "tables": [{"headers": ["Unit", "Calories", "Protein", "Carbs", "Sugar", "Fat", "Fiber"], "rows": [{"Unit": "1 medium banana", "Calories": "105", "Protein": "1.3g", "Carbs": "27g", "Sugar": "14g", "Fat": "0.4g", "Fiber": "3.1g"}]}, {"headers": ["Nutrient", "Amount"], "rows": [{"Nutrient": "Calcium", "Amount": "5.9mg"}, {"Nutrient": "Iron", "Amount": "0.3mg"}, {"Nutrient": "Potassium", "Amount": "422mg"}, {"Nutrient": "Sodium", "Amount": "1.2mg"}]}], "unit": "1 medium banana", "calories": "105", "protein": "1.3g", "carbs": "27g", "sugar": "14g", "fat": "0.4g", "fiber": "3.1g", "quick_reference_servings": [{"Nutrient": "Calcium", "Amount": "5.9mg"}, {"Nutrient": "Iron", "Amount": "0.3mg"}, {"Nutrient": "Potassium", "Amount": "422mg"}, {"Nutrient": "Sodium", "Amount": "1.2mg"}], "tags": "", "food_category": "carb", "source": "notion", "notion_category": "Carb", "serving_unit": "1 medium banana", "calories_per_unit": "105", "protein_per_unit_g": "1.3", "carbs_per_unit_g": "27", "fat_per_unit_g": "0.4", "fiber_per_unit_g": "3.1", "sugar_per_unit_g": "14", "processing_level": "Whole/Unprocessed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Black Beans', 'carb', 120, 8, 22, 0.4, 0, 0, false, '{"content_hash": "de961385f4ddff2c378530e5a105f1bd", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/carb\nfood_category: carb\nsource: notion\nnotion_category: Carb\nserving_unit: \"1/2 cup\"\ncalories_per_unit: 120\nprotein_per_unit_g: 8\ncarbs_per_unit_g: 22\nfat_per_unit_g: 0.4\nfiber_per_unit_g: 9\nsugar_per_unit_g: 0\nprocessing_level: \"Minimally Processed\"\nfermented: false\n---\n# Black Beans\n\nMigrated from Notion''s Foods database. Data is per serving **unit**, not per 100g \u2014 a sparser reference than the vault''s primary food-library entries.\n\n## Macros (per unit)\n\n| Unit | Calories | Protein | Carbs | Sugar | Fat | Fiber |\n|---|---|---|---|---|---|---|\n| 1/2 cup | 120 | 8g | 22g | 0g | 0.4g | 9g |\n\n## Micronutrients (per unit)\n\n| Nutrient | Amount |\n|---|---|\n| Calcium | 3.5mg |\n| Potassium | 50mg |\n| Sodium | 125mg |\n\n## Classification\n\n- **Category:** Carb\n- **Processing Level:** Minimally Processed\n- **Fermented:** No\n", "portion_state": "unspecified", "tables": [{"headers": ["Unit", "Calories", "Protein", "Carbs", "Sugar", "Fat", "Fiber"], "rows": [{"Unit": "1/2 cup", "Calories": "120", "Protein": "8g", "Carbs": "22g", "Sugar": "0g", "Fat": "0.4g", "Fiber": "9g"}]}, {"headers": ["Nutrient", "Amount"], "rows": [{"Nutrient": "Calcium", "Amount": "3.5mg"}, {"Nutrient": "Potassium", "Amount": "50mg"}, {"Nutrient": "Sodium", "Amount": "125mg"}]}], "unit": "1/2 cup", "calories": "120", "protein": "8g", "carbs": "22g", "sugar": "0g", "fat": "0.4g", "fiber": "9g", "quick_reference_servings": [{"Nutrient": "Calcium", "Amount": "3.5mg"}, {"Nutrient": "Potassium", "Amount": "50mg"}, {"Nutrient": "Sodium", "Amount": "125mg"}], "tags": "", "food_category": "carb", "source": "notion", "notion_category": "Carb", "serving_unit": "1/2 cup", "calories_per_unit": "120", "protein_per_unit_g": "8", "carbs_per_unit_g": "22", "fat_per_unit_g": "0.4", "fiber_per_unit_g": "9", "sugar_per_unit_g": "0", "processing_level": "Minimally Processed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Blueberries', 'fruit', 57, 0.7, 14.5, 0.3, 2.4, 58, false, '{"content_hash": "d949f9480fa8f9ba8e31935dc891734a", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/fruit\nfood_category: fruit\n# Macros per 100g\ncalories_per_100g: 57\nprotein_per_100g: 0.7\ncarbs_per_100g: 14.5\nsugar_per_100g: 9.96\nadded_sugar: false\nfat_per_100g: 0.3\nsaturated_fat_per_100g: 0.0\nfibre_per_100g: 2.4\ncholesterol_per_100g: 0\n# Omega-3\nomega3_per_100g_mg: 58\n# Key minerals per 100g (mg unless noted)\niron_per_100g: 0.3\nzinc_per_100g: 0.2\nmagnesium_per_100g: 6\npotassium_per_100g: 77\nsodium_per_100g: 1\nselenium_per_100g_\u00b5g: 0.1\ncholine_per_100g_mg: 6\n# Key vitamins per 100g\nvitamin_c_per_100g_mg: 9.7\nvitamin_d_per_100g_iu: 0\nvitamin_b12_per_100g_\u00b5g: 0\n# Protein quality\ncomplete_protein: false\nleucine_per_100g: 0.07\n# Good Energy attributes\nantioxidant_level: high\nprobiotic: false\nrefined: false\nseed_oil: false\n# Body systems\nbody_systems:\n  - brain\n  - mitochondria\n  - eyes\n  - gut\n  - heart\n  - immune\n# Serving\nserving_unit: g\nserving_unit_g: 1\ntypical_serving: 80g\ntypical_serving_g: 80\n# Classification\nglycaemic_index: 53\nmitochondrial_benefit: high\n---\n# Blueberries\n\n> [!success] Sports Nutrition Snapshot\n> **Anthocyanins: ~165mg / 100g** \u00b7 **GI: 53** \u00b7 **Mitochondrial benefit: High**\n> The highest-priority fruit in the Good Energy framework \u2014 one of few foods that directly activates mitochondrial biogenesis via PGC-1\u03b1.\n\n> [!quote]\n> \"Blueberries are the most studied berry for mitochondrial and cognitive health. The anthocyanins cross the blood-brain barrier \u2014 they are feeding your neurons directly.\" \u2014 Rhonda Patrick\n\nBlueberries are low-calorie, moderate-GI, and exceptionally rich in anthocyanins \u2014 the polyphenols responsible for the deep blue-purple pigment. Anthocyanins cross the blood-brain barrier (rare for dietary compounds), activate PGC-1\u03b1 (the master regulator of mitochondrial biogenesis), and exert powerful anti-inflammatory effects throughout the body. Despite containing natural sugars, the anti-glycaemic properties of their polyphenols make them metabolically unique among fruits.\n\n---\n\n## Macros\n\n### Per 100g\n\n| Calories | Protein | Carbs | Sugar | Fat | Sat. Fat | Fibre | Cholesterol |\n|---|---|---|---|---|---|---|---|\n| 57 | 0.7g | 14.5g | 9.96g | 0.3g | 0g | 2.4g | 0mg |\n\n### Quick Reference\n\n| Amount | Cal | Carbs | Sugar | Fibre | Vitamin C | Anthocyanins |\n|---|---|---|---|---|---|---|\n| 80g | 46 | 11.6g | 8.0g | 1.9g | 7.8mg | ~132mg |\n| 100g | 57 | 14.5g | 9.96g | 2.4g | 9.7mg | ~165mg |\n| 150g | 86 | 21.8g | 14.9g | 3.6g | 14.6mg | ~248mg |\n\n---\n\n## Minerals\n\n| Mineral | Per 100g | % RDA | Role |\n|---|---|---|---|\n| Manganese | 0.3mg | 13\u201315% | Mitochondrial SOD2 antioxidant enzyme cofactor |\n| Potassium | 77mg | 2% | Electrolyte balance |\n| Copper | 0.06mg | 7% | SOD1 cofactor; iron metabolism |\n| Iron | 0.3mg | 2\u20134% | Oxygen transport |\n| Magnesium | 6mg | 1% | ATP synthesis (minimal contribution) |\n\n---\n\n## Vitamins\n\n| Vitamin | Per 100g | % RDA | Role |\n|---|---|---|---|\n| Vitamin K | 19\u00b5g | 16\u201323% | Bone mineralisation; coagulation |\n| Vitamin C | 9.7mg | 11% | Antioxidant; collagen synthesis; iron absorption |\n| Vitamin E | 0.6mg | 4% | Fat-soluble antioxidant |\n| Folate | 6\u00b5g | 2% | DNA synthesis; methylation |\n\n---\n\n## Polyphenol Profile\n\n> [!tip] Anthocyanins \u2014 the primary bioactive compound\n> Anthocyanins are water-soluble pigments in the flavonoid family. Blueberries are among the richest dietary sources, and their small molecular size allows them to cross the blood-brain barrier \u2014 a property rare among dietary compounds.\n\n| Compound | Per 100g | Key Actions |\n|---|---|---|\n| Total anthocyanins | ~165mg | PGC-1\u03b1 activation; anti-inflammatory; neuroprotective |\n| Quercetin | ~7.7mg | Anti-inflammatory; antiviral; mast cell stabiliser |\n| Myricetin | ~5.3mg | Anti-inflammatory; anticancer; neuroprotective |\n| Chlorogenic acid | ~9.8mg | Anti-glycaemic; antioxidant; liver protective |\n| Pterostilbene | trace | Resveratrol analogue; higher bioavailability; epigenetic effects |\n\n> [!info] PGC-1\u03b1 and mitochondrial biogenesis\n> PGC-1\u03b1 is the master transcription factor for mitochondrial biogenesis \u2014 it signals the cell to make more mitochondria. Anthocyanins from blueberries are one of the few dietary compounds with evidence for directly activating PGC-1\u03b1. This is why blueberries are considered mitochondrially supportive despite being primarily a carbohydrate source.\n\n---\n\n## Food Synergies\n\n| Paired With | Synergy | Mechanism |\n|---|---|---|\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] | Fat-soluble phytonutrient absorption | Avocado''s monounsaturated fat significantly increases bioavailability of blueberries'' fat-soluble polyphenols (beta-carotene, lutein); the absorption of polyphenols generally improves substantially when co-ingested with dietary fat |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] | Double anti-glycaemic effect | Beta-glucan (oats) + anthocyanins (blueberries) independently blunt glucose absorption; together the effect is additive; the combination is one of the most evidence-backed breakfast choices for metabolic health |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]] | Brain health synergy | DHA (salmon) provides structural substrate for neuronal membranes while anthocyanins (blueberries) reduce neuroinflammation and stimulate BDNF \u2014 synergistic for neuroplasticity and cognitive function |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] | Post-training recovery pair | Anthocyanins reduce exercise-induced oxidative stress; egg protein and leucine drive muscle protein synthesis \u2014 a complementary recovery combination |\n\n---\n\n## Dosage Guidance\n\n> [!info] Optimal range and practical notes\n> **Optimal: 80\u2013150g per day**\n> - Below 80g: anthocyanin dose falls below levels used in most cognitive and mitochondrial benefit studies\n> - 80\u2013150g is the functional range for polyphenol benefit without excessive natural sugar load\n> - Above 150g: natural sugars accumulate (9.96g sugar per 100g); diminishing returns on antioxidant benefit per calorie\n>\n> **Wild blueberries:** 2\u20133\u00d7 higher anthocyanin content than cultivated (smaller berries, more skin per gram, deeper colour). Specifically superior for cognitive and mitochondrial applications if available.\n>\n> **Frozen = equally nutritious:** blueberries are frozen at peak ripeness, which preserves anthocyanin content. Out-of-season fresh blueberries are often lower in anthocyanins than frozen. No meaningful nutritional reason to prefer fresh unless in season.\n>\n> **No upper limit concern** for healthy individuals. Blueberries are essentially a free food from a calorie and glycaemic standpoint \u2014 the natural sugar is buffered by fibre and by the anti-glycaemic effect of the anthocyanins themselves.\n\n---\n\n## Good Energy Relevance\n\nDespite containing natural sugars (9.96g/100g), blueberries have a moderate GI (53) and a meaningful anti-glycaemic effect \u2014 their anthocyanins inhibit alpha-glucosidase (the enzyme that breaks down complex carbohydrates into glucose), independently reducing post-meal glucose. Long-term studies show blueberry consumption improves insulin sensitivity. The PGC-1\u03b1 activation is the direct mitochondrial link \u2014 making blueberries one of the few foods that supports all three of Means'' primary targets simultaneously: glucose management, mitochondrial health, and antioxidant protection.\n\n**Good Energy daily targets contribution (per 80g):**\n- Fibre: 1.9g of 50g target (4%)\n- Omega-3: 46mg of 2,000mg target (ALA, trace)\n- Antioxidants: high (anthocyanins, quercetin, chlorogenic acid)\n- Probiotics: none (but polyphenols act as prebiotics \u2014 selectively feeding beneficial gut bacteria)\n\n---\n\n## Meal Ideas\n\nWith oats at breakfast \u00b7 Mixed into Greek yogurt \u00b7 As a post-training snack with eggs \u00b7 Frozen blueberries are equally effective \u2014 often preferred for year-round consistency\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Oats]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Salmon]]\n", "portion_state": "unspecified", "tables": [{"headers": ["Calories", "Protein", "Carbs", "Sugar", "Fat", "Sat. Fat", "Fibre", "Cholesterol"], "rows": [{"Calories": "57", "Protein": "0.7g", "Carbs": "14.5g", "Sugar": "9.96g", "Fat": "0.3g", "Sat. Fat": "0g", "Fibre": "2.4g", "Cholesterol": "0mg"}]}, {"headers": ["Amount", "Cal", "Carbs", "Sugar", "Fibre", "Vitamin C", "Anthocyanins"], "rows": [{"Amount": "80g", "Cal": "46", "Carbs": "11.6g", "Sugar": "8.0g", "Fibre": "1.9g", "Vitamin C": "7.8mg", "Anthocyanins": "~132mg"}, {"Amount": "100g", "Cal": "57", "Carbs": "14.5g", "Sugar": "9.96g", "Fibre": "2.4g", "Vitamin C": "9.7mg", "Anthocyanins": "~165mg"}, {"Amount": "150g", "Cal": "86", "Carbs": "21.8g", "Sugar": "14.9g", "Fibre": "3.6g", "Vitamin C": "14.6mg", "Anthocyanins": "~248mg"}]}, {"headers": ["Mineral", "Per 100g", "% RDA", "Role"], "rows": [{"Mineral": "Manganese", "Per 100g": "0.3mg", "% RDA": "13\u201315%", "Role": "Mitochondrial SOD2 antioxidant enzyme cofactor"}, {"Mineral": "Potassium", "Per 100g": "77mg", "% RDA": "2%", "Role": "Electrolyte balance"}, {"Mineral": "Copper", "Per 100g": "0.06mg", "% RDA": "7%", "Role": "SOD1 cofac