insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Lean Fit Whey Protein Vanilla Bean', 'protein', 140, 24, 2, 3.5, 0, 0, false, '{"content_hash": "56b8fb44a9bf8dbf76b7098a158bd98a", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/protein\nfood_category: protein\nsource: notion\nnotion_category: Protein\nserving_unit: \"1 scoop\"\ncalories_per_unit: 140\nprotein_per_unit_g: 24\ncarbs_per_unit_g: 2\nfat_per_unit_g: 3.5\nfiber_per_unit_g: 0\nsugar_per_unit_g: 2\ncholesterol_per_unit_mg: 70\nleucine_per_unit_g: 2.28\nprocessing_level: \"Ultra-Processed\"\nfermented: false\n---\n# Lean Fit Whey Protein Vanilla Bean\n\nMigrated from Notion''s Foods database. Data is per serving **unit**, not per 100g \u2014 a sparser reference than the vault''s primary food-library entries.\n\n## Macros (per unit)\n\n| Unit | Calories | Protein | Carbs | Sugar | Fat | Fiber | Cholesterol | Leucine |\n|---|---|---|---|---|---|---|---|---|\n| 1 scoop | 140 | 24g | 2g | 2g | 3.5g | 0g | 70mg | 2.28g |\n\n## Micronutrients (per unit)\n\n| Nutrient | Amount |\n|---|---|\n| Calcium | 150mg |\n| Iron | 0.5mg |\n| Potassium | 250mg |\n| Sodium | 125mg |\n\n## Classification\n\n- **Category:** Protein\n- **Processing Level:** Ultra-Processed\n- **Fermented:** No\n\n## Health Benefits\n\nAids muscle recovery and growth, convenient protein boost.\n\n## Notes\n\nIdeal post-workout. Used as the whey source in the [[Post-Workout Shake]] recipe.\n", "portion_state": "unspecified", "tables": [{"headers": ["Unit", "Calories", "Protein", "Carbs", "Sugar", "Fat", "Fiber", "Cholesterol", "Leucine"], "rows": [{"Unit": "1 scoop", "Calories": "140", "Protein": "24g", "Carbs": "2g", "Sugar": "2g", "Fat": "3.5g", "Fiber": "0g", "Cholesterol": "70mg", "Leucine": "2.28g"}]}, {"headers": ["Nutrient", "Amount"], "rows": [{"Nutrient": "Calcium", "Amount": "150mg"}, {"Nutrient": "Iron", "Amount": "0.5mg"}, {"Nutrient": "Potassium", "Amount": "250mg"}, {"Nutrient": "Sodium", "Amount": "125mg"}]}], "unit": "1 scoop", "calories": "140", "protein": "24g", "carbs": "2g", "sugar": "2g", "fat": "3.5g", "fiber": "0g", "cholesterol": "70mg", "leucine": "2.28g", "quick_reference_servings": [{"Nutrient": "Calcium", "Amount": "150mg"}, {"Nutrient": "Iron", "Amount": "0.5mg"}, {"Nutrient": "Potassium", "Amount": "250mg"}, {"Nutrient": "Sodium", "Amount": "125mg"}], "tags": "", "food_category": "protein", "source": "notion", "notion_category": "Protein", "serving_unit": "1 scoop", "calories_per_unit": "140", "protein_per_unit_g": "24", "carbs_per_unit_g": "2", "fat_per_unit_g": "3.5", "fiber_per_unit_g": "0", "sugar_per_unit_g": "2", "cholesterol_per_unit_mg": "70", "leucine_per_unit_g": "2.28", "processing_level": "Ultra-Processed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Lentils', 'carb', 115, 9, 20, 0.4, 0, 0, false, '{"content_hash": "7bf0e3a7cd4c9abb78bbd9b7ab940e8f", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/carb\nfood_category: carb\nsource: notion\nnotion_category: Carb\nserving_unit: \"1/2 cup cooked (assumed)\"\ncalories_per_unit: 115\nprotein_per_unit_g: 9\ncarbs_per_unit_g: 20\nfat_per_unit_g: 0.4\nsugar_per_unit_g: 2\nprocessing_level: \"Whole/Unprocessed\"\nfermented: false\n---\n# Lentils\n\nMigrated from Notion''s Foods database. Data is per serving **unit**, not per 100g \u2014 a sparser reference than the vault''s primary food-library entries.\n\n## Macros (per unit)\n\n| Unit | Calories | Protein | Carbs | Sugar | Fat |\n|---|---|---|---|---|---|\n| 1/2 cup cooked (assumed) | 115 | 9g | 20g | 2g | 0.4g |\n\n## Classification\n\n- **Category:** Carb\n- **Processing Level:** Whole/Unprocessed\n- **Fermented:** No\n\n## Health Benefits\n\nExcellent source of fiber and folate, good for heart health and digestion.\n\n## Notes\n\nServing size inferred from macros, not explicit in source \u2014 please verify. Quick-cooking, great in soups or curries.\n", "portion_state": "cooked", "tables": [{"headers": ["Unit", "Calories", "Protein", "Carbs", "Sugar", "Fat"], "rows": [{"Unit": "1/2 cup cooked (assumed)", "Calories": "115", "Protein": "9g", "Carbs": "20g", "Sugar": "2g", "Fat": "0.4g"}]}], "unit": "1/2 cup cooked (assumed)", "calories": "115", "protein": "9g", "carbs": "20g", "sugar": "2g", "fat": "0.4g", "tags": "", "food_category": "carb", "source": "notion", "notion_category": "Carb", "serving_unit": "1/2 cup cooked (assumed)", "calories_per_unit": "115", "protein_per_unit_g": "9", "carbs_per_unit_g": "20", "fat_per_unit_g": "0.4", "sugar_per_unit_g": "2", "processing_level": "Whole/Unprocessed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
