"Potassium", "Amount": "376mg"}, {"Nutrient": "Sodium", "Amount": "480mg"}, {"Nutrient": "Vitamin C", "Amount": "62mg"}], "tags": "", "food_category": "supplement", "source": "notion", "notion_category": "Supplement", "serving_unit": "1 packet", "calories_per_unit": "10", "protein_per_unit_g": "0", "carbs_per_unit_g": "2", "fat_per_unit_g": "0", "fiber_per_unit_g": "0", "sugar_per_unit_g": "0", "processing_level": "Ultra-Processed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
