0mg"}, {"Nutrient": "Sodium", "Amount": "25mg"}, {"Nutrient": "Vitamin A", "Amount": "165mcg"}, {"Nutrient": "Vitamin C", "Amount": "25mg"}]}], "unit": "3/4 cup (85g)", "calories": "25", "protein": "2g", "carbs": "5g", "sugar": "2g", "fat": "0g", "fiber": "3g", "cholesterol": "0mg", "quick_reference_servings": [{"Nutrient": "Calcium", "Amount": "30mg"}, {"Nutrient": "Iron", "Amount": "0.5mg"}, {"Nutrient": "Potassium", "Amount": "150mg"}, {"Nutrient": "Sodium", "Amount": "25mg"}, {"Nutrient": "Vitamin A", "Amount": "165mcg"}, {"Nutrient": "Vitamin C", "Amount": "25mg"}], "tags": "", "food_category": "produce", "source": "notion", "notion_category": "Produce", "serving_unit": "3/4 cup (85g)", "serving_unit_g": "85", "calories_per_unit": "25", "protein_per_unit_g": "2", "carbs_per_unit_g": "5", "fat_per_unit_g": "0", "fiber_per_unit_g": "3", "sugar_per_unit_g": "2", "cholesterol_per_unit_mg": "0", "processing_level": "Minimally Processed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
insert into food_library (name, food_category, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fibre_per_100g, omega3_per_100g_mg, seed_oil, raw_payload) values ('Oats', 'carb', 379, 13.2, 67.7, 6.9, 10.6, 110, false, '{"content_hash": "b4623daa51f06c6db1bab986302ae7bb", "full_markdown_content": "---\ntags:\n  - nutrition/food\n  - nutrition/food/carb\nfood_category: carb\n# Macros per 100g (dry weight)\ncalories_per_100g: 379\nprotein_per_100g: 13.2\ncarbs_per_100g: 67.7\nsugar_per_100g: 1.1\nadded_sugar: false\nfat_per_100g: 6.9\nsaturated_fat_per_100g: 1.2\nfibre_per_100g: 10.6\ncholesterol_per_100g: 0\n# Omega-3\nomega3_per_100g_mg: 110\n# Key minerals per 100g (mg unless noted)\niron_per_100g: 4.7\nzinc_per_100g: 3.6\nmagnesium_per_100g: 138\npotassium_per_100g: 429\nsodium_per_100g: 2\nselenium_per_100g_\u00b5g: 28\ncholine_per_100g_mg: 40\n# Key vitamins per 100g\nvitamin_c_per_100g_mg: 0\nvitamin_d_per_100g_iu: 0\nvitamin_b12_per_100g_\u00b5g: 0\n# Protein quality\ncomplete_protein: false\nleucine_per_100g: 1.05\n# Good Energy attributes\nantioxidant_level: moderate\nprobiotic: false\nrefined: false\nseed_oil: false\n# Body systems\nbody_systems:\n  - gut\n  - heart\n  - muscles\n  - mitochondria\n  - immune\n# Serving\nserving_unit: g\nserving_unit_g: 1\ntypical_serving: 60g dry\ntypical_serving_g: 60\n# Classification\nglycaemic_index: 55\nmitochondrial_benefit: moderate\n---\n# Oats\n\n> [!success] Sports Nutrition Snapshot\n> **Beta-glucan: 5.7g / 100g dry** \u00b7 **GI: 55 (moderate)** \u00b7 **Mitochondrial benefit: Moderate**\n> The most fibre-dense grain for everyday use \u2014 and one of the few foods with clinical trial evidence for blunting the glucose spike.\n\n> [!quote]\n> \"Oats are one of the few grains with a meaningful beta-glucan content \u2014 a fibre that has been shown in clinical trials to blunt the post-meal glucose spike and improve insulin sensitivity.\" \u2014 Casey Means\n\nRolled oats are the most practical high-fibre carbohydrate for everyday eating. Beta-glucan \u2014 the soluble fibre unique to oats \u2014 forms a viscous gel in the gut that slows glucose absorption, feeds beneficial bacteria, and produces short-chain fatty acids (SCFAs) that reduce systemic inflammation. Oats also contain avenanthramides, polyphenols unique to oats with anti-inflammatory and cardioprotective properties.\n\n> [!info] All macros are for dry weight\n> 60g dry oats \u2192 roughly 1 cup cooked (with water). Nutrition facts reflect dry weight throughout.\n\n---\n\n## Macros\n\n### Per 100g (dry)\n\n| Calories | Protein | Carbs | Sugar | Fat | Sat. Fat | Fibre | Cholesterol |\n|---|---|---|---|---|---|---|---|\n| 379 | 13.2g | 67.7g | 1.1g | 6.9g | 1.2g | 10.6g | 0mg |\n\n### Quick Reference\n\n| Amount (dry) | Cal | Protein | Carbs | Fat | Fibre | Beta-glucan |\n|---|---|---|---|---|---|---|\n| 40g | 152 | 5.3g | 27.1g | 2.8g | 4.2g | ~2.3g |\n| 60g | 227 | 7.9g | 40.6g | 4.1g | 6.4g | ~3.4g |\n| 80g | 303 | 10.6g | 54.2g | 5.5g | 8.5g | ~4.6g |\n| 100g | 379 | 13.2g | 67.7g | 6.9g | 10.6g | ~5.7g |\n\n> [!info] Beta-glucan threshold\n> 3g of beta-glucan per meal is the clinically established dose for meaningful LDL reduction and glucose blunting. **60g dry oats provides ~3.4g** \u2014 just above the threshold. Going below 50g dry risks falling short of the functional dose.\n\n---\n\n## Minerals\n\n| Mineral | Per 100g | % RDA | Role |\n|---|---|---|---|\n| Manganese | 4.9mg | 213\u2013245% | Cofactor for mitochondrial superoxide dismutase (SOD2) \u2014 the primary antioxidant inside the mitochondrion |\n| Phosphorus | 523mg | 42% | ATP production; bone mineralisation |\n| Iron | 4.7mg | 26\u201359% | Oxygen transport; mitochondrial electron chain |\n| Zinc | 3.6mg | 33\u201345% | Protein synthesis; immune function; testosterone |\n| Magnesium | 138mg | 33% | ATP synthesis; >300 enzymatic reactions; commonly deficient |\n| Potassium | 429mg | 9% | Electrolyte balance; muscle contraction |\n| Selenium | 28\u00b5g | 51% | Antioxidant defence; thyroid function |\n\n> [!info] Manganese and Mitochondria\n> Oats are one of the richest dietary sources of manganese \u2014 the essential cofactor for SOD2, the enzyme that neutralises superoxide radicals inside the mitochondrion. This is the cell''s primary internal antioxidant defence; manganese deficiency directly impairs mitochondrial function.\n\n---\n\n## Vitamins\n\n| Vitamin | Per 100g | % RDA | Role |\n|---|---|---|---|\n| Thiamine (B1) | 0.8mg | 67\u201373% | Glucose metabolism \u2014 the gatekeeper enzyme for converting carbohydrates to mitochondrial fuel |\n| Niacin (B3) | 1.1mg | 7% | NAD+ precursor; electron carrier in energy production |\n| Vitamin E | 1.5mg | 10% | Fat-soluble antioxidant; protects polyunsaturated fats from oxidation |\n| Folate | 56\u00b5g | 14% | DNA synthesis; methylation reactions |\n\n---\n\n## Fibre Profile\n\n| Fibre Type | Per 100g | Role |\n|---|---|---|\n| Beta-glucan (soluble) | ~5.7g | Forms viscous gel; blunts glucose absorption; feeds Lactobacillus and Bifidobacterium; clinical evidence for LDL reduction |\n| Insoluble fibre | ~4.9g | Increases stool bulk; transit time; feeds different gut bacteria |\n| **Total fibre** | **10.6g** | **22% of the Good Energy 50g/day target in 100g dry oats** |\n\n---\n\n## Food Synergies\n\n| Paired With | Synergy | Mechanism |\n|---|---|---|\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] | Glucose blunting | Eating eggs (protein + fat) before or with oats significantly blunts the glucose spike; the fat and protein slow gastric emptying and reduce the glycaemic response of the carbohydrate |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] | Double anti-glycaemic effect | Beta-glucan (oats) + anthocyanins (blueberries) both independently reduce post-meal glucose; together the effect is additive; anthocyanins also activate PGC-1\u03b1 to improve mitochondrial use of the carbohydrate energy |\n| [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]] / nut butter | Fat-mediated glucose dampening | Additional fat further reduces glucose response; useful on rest days when the same carbohydrate load causes a larger spike |\n| Pre-workout carbohydrate | Glycogen loading | Eaten 2\u20133 hours before training, oats provide sustained glycogen without GI distress \u2014 a reliable pre-training fuel |\n\n---\n\n## Dosage Guidance\n\n> [!warning] Timing matters more than amount\n> **Optimal serving: 60\u201380g dry**\n> - 60g provides the beta-glucan threshold (~3.4g) and 40.6g carbs \u2014 sufficient pre-training fuel\n> - 80g provides more fibre (8.5g) but 54g carbs \u2014 more appropriate for heavy training days\n>\n> **Morning is strongly preferred:** glucose tolerance is highest in the morning; the same 60g oat portion causes a ~30% larger glucose spike when eaten in the evening vs. 7\u20138am. This is a circadian effect, not a food quality issue.\n>\n> **Not for low-carb or rest days** if carbohydrate is being reduced \u2014 60g dry = 40.6g carbs is a significant glucose load. On rest days, substitute a lower-carb option or reduce portion to 40g.\n>\n> **Avoid instant oats:** heat processing degrades beta-glucan structure, reducing the functional fibre dose. Rolled oats (5-minute) or steel-cut oats preserve the beta-glucan intact.\n\n---\n\n## Good Energy Relevance\n\nOats contribute meaningfully to the Good Energy framework''s 50g/day fibre target \u2014 one of the highest among common foods. The beta-glucan feeds the gut microbiome that produces SCFAs, which independently improve insulin sensitivity and reduce gut inflammation. Moderate GI (55) combined with beta-glucan gel means the glucose response in practice is lower than the GI number implies \u2014 especially when combined with eggs.\n\n**Good Energy daily targets contribution (per 60g dry):**\n- Fibre: 6.4g of 50g target (13%)\n- Omega-3: 66mg of 2,000mg target (ALA, poorly converted)\n- Antioxidants: moderate (avenanthramides, manganese-SOD2)\n- Probiotics: none (but beta-glucan is a prebiotic that feeds probiotic bacteria)\n\n---\n\n## Meal Ideas\n\nCooked with eggs and blueberries (breakfast) \u00b7 Overnight oats with blueberries \u00b7 Pre-workout carbohydrate source 2\u20133 hours before training\n\n**Pairs well with:** [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Blueberries]] \u00b7 [[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Avocado]]\n", "portion_state": "cooked", "tables": [{"headers": ["Calories", "Protein", "Carbs", "Sugar", "Fat", "Sat. Fat", "Fibre", "Cholesterol"], "rows": [{"Calories": "379", "Protein": "13.2g", "Carbs": "67.7g", "Sugar": "1.1g", "Fat": "6.9g", "Sat. Fat": "1.2g", "Fibre": "10.6g", "Cholesterol": "0mg"}]}, {"headers": ["Amount (dry)", "Cal", "Protein", "Carbs", "Fat", "Fibre", "Beta-glucan"], "rows": [{"Amount (dry)": "40g", "Cal": "152", "Protein": "5.3g", "Carbs": "27.1g", "Fat": "2.8g", "Fibre": "4.2g", "Beta-glucan": "~2.3g"}, {"Amount (dry)": "60g", "Cal": "227", "Protein": "7.9g", "Carbs": "40.6g", "Fat": "4.1g", "Fibre": "6.4g", "Beta-glucan": "~3.4g"}, {"Amount (dry)": "80g", "Cal": "303", "Protein": "10.6g", "Carbs": "54.2g", "Fat": "5.5g", "Fibre": "8.5g", "Beta-glucan": "~4.6g"}, {"Amount (dry)": "100g", "Cal": "379", "Protein": "13.2g", "Carbs": "67.7g", "Fat": "6.9g", "Fibre": "10.6g", "Beta-glucan": "~5.7g"}]}, {"headers": ["Mineral", "Per 100g", "% RDA", "Role"], "rows": [{"Mineral": "Manganese", "Per 100g": "4.9mg", "% RDA": "213\u2013245%", "Role": "Cofactor for mitochondrial superoxide dismutase (SOD2) \u2014 the primary antioxidant inside the mitochondrion"}, {"Mineral": "Phosphorus", "Per 100g": "523mg", "% RDA": "42%", "Role": "ATP production; bone mineralisation"}, {"Mineral": "Iron", "Per 100g": "4.7mg", "% RDA": "26\u201359%", "Role": "Oxygen transport; mitochondrial electron chain"}, {"Mineral": "Zinc", "Per 100g": "3.6mg", "% RDA": "33\u201345%", "Role": "Protein synthesis; immune function; testosterone"}, {"Mineral": "Magnesium", "Per 100g": "138mg", "% RDA": "33%", "Role": "ATP synthesis; >300 enzymatic reactions; commonly deficient"}, {"Mineral": "Potassium", "Per 100g": "429mg", "% RDA": "9%", "Role": "Electrolyte balance; muscle contraction"}, {"Mineral": "Selenium", "Per 100g": "28\u00b5g", "% RDA": "51%", "Role": "Antioxidant defence; thyroid function"}]}, {"headers": ["Vitamin", "Per 100g", "% RDA", "Role"], "rows": [{"Vitamin": "Thiamine (B1)", "Per 100g": "0.8mg", "% RDA": "67\u201373%", "Role": "Glucose metabolism \u2014 the gatekeeper enzyme for converting carbohydrates to mitochondrial fuel"}, {"Vitamin": "Niacin (B3)", "Per 100g": "1.1mg", "% RDA": "7%", "Role": "NAD+ precursor; electron carrier in energy production"}, {"Vitamin": "Vitamin E", "Per 100g": "1.5mg", "% RDA": "10%", "Role": "Fat-soluble antioxidant; protects polyunsaturated fats from oxidation"}, {"Vitamin": "Folate", "Per 100g": "56\u00b5g", "% RDA": "14%", "Role": "DNA synthesis; methylation reactions"}]}, {"headers": ["Fibre Type", "Per 100g", "Role"], "rows": [{"Fibre Type": "Beta-glucan (soluble)", "Per 100g": "~5.7g", "Role": "Forms viscous gel; blunts glucose absorption; feeds Lactobacillus and Bifidobacterium; clinical evidence for LDL reduction"}, {"Fibre Type": "Insoluble fibre", "Per 100g": "~4.9g", "Role": "Increases stool bulk; transit time; feeds different gut bacteria"}, {"Fibre Type": "**Total fibre**", "Per 100g": "**10.6g**", "Role": "**22% of the Good Energy 50g/day target in 100g dry oats**"}]}, {"headers": ["Paired With", "Synergy", "Mechanism"], "rows": [{"Paired With": "[[\ud83c\udf9b\ufe0f Control Center/Supabase Data/Foods/Eggs]]", "Synergy": "Glucose blunting", "Mechanism": "Eating eggs (protein + fat) before or with oats significantly blunts the glucose spike; the fat and protein slow gastric emptying and reduce the glycaemic response of the carbohydrate"},