"calories": "170", "protein": "11g", "carbs": "29g", "sugar": "2g", "fat": "2.5g", "fiber": "8g", "cholesterol": "0mg", "quick_reference_servings": [{"Nutrient": "Calcium", "Amount": "40mg"}, {"Nutrient": "Iron", "Amount": "2mg"}, {"Nutrient": "Magnesium", "Amount": "60mg"}, {"Nutrient": "Potassium", "Amount": "150mg"}, {"Nutrient": "Sodium", "Amount": "340mg"}, {"Nutrient": "Zinc", "Amount": "1.25mg"}], "tags": "", "food_category": "carb", "source": "notion", "notion_category": "Carb", "serving_unit": "2 slices (75g)", "serving_unit_g": "75", "calories_per_unit": "170", "protein_per_unit_g": "11", "carbs_per_unit_g": "29", "fat_per_unit_g": "2.5", "fiber_per_unit_g": "8", "sugar_per_unit_g": "2", "cholesterol_per_unit_mg": "0", "processing_level": "Processed", "fermented": "false", "callouts": [], "quotes": []}'::jsonb) on conflict (name) do update set calories_per_100g = excluded.calories_per_100g, protein_per_100g = excluded.protein_per_100g, raw_payload = excluded.raw_payload;
